// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address _baseToken) public {
        // baseToken must not be the zero address for the difference to be observable,
        // but we want the property to hold for any valid input given to initialize.
        // initialize requires _feeRate <= 5000, so we use 0.
        c.initialize(_baseToken, address(0), 0, 0, 0, 0, bytes32(0), false, false);
        assertEq(c.baseToken(), _baseToken);
    }
}

